// CLAUDE_PLUGIN_ROOT のどちらも、その場所を検査せよという指定なので名前を返す。
// specified が false で CLAUDE_PLUGIN_ROOT も空のときは、パスにも名前にも空を返す。
// このとき判定フローの検査はデフォルトのパスを読み、ファイルが無くても未導入として
// 通過する (judgmentFlowProblems は名前が空なら不在を報告しない)。名前を返すのは、
// 不在の報告にどちらを直せばよいかを載せるため。
//
// 指定の有無は値ではなく specified (呼び出し元が flag.Visit で読んだ意思表示) で
// 判定する。値が空かどうかで見ると、-judgment-flow "" の明示指定が「指定なし」として
// 扱われ、検査が実行されないまま成功する (-record-dir で避けたはずの種類の欠陥と同じ)。
func resolveJudgmentFlowPath(value string, specified bool) (flowPath, origin string) {
	if specified {
		return value, "-judgment-flow"
	}
	root := os.Getenv("CLAUDE_PLUGIN_ROOT")
	if root == "" {
		return "", ""
	}
	return filepath.Join(root, "skills", "review-triage", "references", "judgment-flow.md"), "CLAUDE_PLUGIN_ROOT"
}

